# Spot two attack patterns in a firewall log: a port scan and a SYN flood.
from collections import defaultdict

log = [  # (source IP, destination port, TCP flags, completed handshake?)
    ('203.0.113.7', p, 'SYN', False) for p in (21, 22, 23, 25, 80, 110, 143, 443, 445, 3389, 8080, 8443)
] + [
    (f'198.51.100.{i}', 443, 'SYN', False) for i in range(1, 41)
] + [
    ('10.10.10.25', 443, 'SYN', True), ('10.10.10.26', 443, 'SYN', True),
]

ports = defaultdict(set)
half_open = defaultdict(int)
for src, port, flags, completed in log:
    ports[src].add(port)
    if flags == 'SYN' and not completed:
        half_open[port] += 1

for src, seen in ports.items():
    if len(seen) >= 10:
        print(f'Possible port scan from {src}: {len(seen)} ports probed')
for port, count in half_open.items():
    sources = {s for s, p, _, c in log if p == port and not c}
    if count >= 30 and len(sources) >= 20:
        print(f'Possible SYN flood on port {port}: {count} half-open connections from {len(sources)} sources')
